"""Shared, embedded visual language for the reliability studio. No network assets."""
BASE_CSS = r'''
:root{color-scheme:dark;--bg:#090e11;--surface:#10181d;--raised:#162128;--border:#253238;--text:#edf4f3;--muted:#94a6ad;--mint:#bcf783;--violet:#b9a4ff;--cyan:#7fdbed;--danger:#ff9b9b;--amber:#f5cd88;--sans:Inter,ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;--mono:ui-monospace,SFMono-Regular,Consolas,monospace}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 78% -10%,#18342c66,transparent 44%),var(--bg);color:var(--text);font:14px var(--sans);-webkit-font-smoothing:antialiased}button,select,input{font:inherit;color:inherit}button,summary,select{cursor:pointer}button:disabled{cursor:default;opacity:.4}a{color:inherit}button,a,input,select,summary{outline-offset:5px}*:focus-visible{outline:2px solid var(--mint)}[hidden]{display:none!important}.studio-shell{max-width:1520px;padding:0 42px 28px;margin:auto;min-width:0}.app-nav{display:flex;align-items:center;gap:36px;min-height:83px;border-bottom:1px solid var(--border);margin-bottom:0}.wordmark{display:flex;gap:10px;align-items:center;text-decoration:none;white-space:nowrap;font-size:19px;font-weight:650;letter-spacing:-.7px}.wordmark svg{width:31px;height:31px;color:var(--mint)}.wordmark small{font:9px var(--mono);color:var(--muted);border:1px solid var(--border);border-radius:4px;padding:3px 5px;margin-left:5px;letter-spacing:.5px}.app-tabs{display:flex;gap:5px;padding:4px;background:#060b0e;border:1px solid var(--border);border-radius:10px}.app-tabs a{display:flex;align-items:center;gap:8px;text-decoration:none;font-size:12px;color:var(--muted);padding:10px 16px;border-radius:6px;white-space:nowrap}.app-tabs a[aria-current]{background:var(--raised);color:var(--text);box-shadow:0 1px 4px #0004}.tab-icon{width:14px;height:14px;opacity:.85}.nav-status{display:flex;align-items:center;gap:8px;margin-left:auto;color:var(--muted);font:10px var(--mono);white-space:nowrap}.status-dot{width:6px;height:6px;border-radius:50%;background:var(--mint);box-shadow:0 0 12px #bcf78344}.studio-hero{padding:39px 0 29px;display:flex;align-items:center;justify-content:space-between;gap:30px}.eyebrow{font:10px var(--mono);color:var(--mint);letter-spacing:1.5px;text-transform:uppercase;margin-bottom:14px;display:flex;align-items:center;gap:10px}.eyebrow:before{content:'';display:inline-block;width:20px;height:1px;background:var(--mint)}.studio-hero h1{font-size:clamp(32px,3.5vw,49px);line-height:1.12;letter-spacing:-2px;font-weight:550;margin:0 0 14px}.studio-hero h1 em{color:var(--mint);font-style:normal}.studio-hero p{color:var(--muted);font-size:13px;line-height:1.8;max-width:550px;margin:0}.hero-aside{display:flex;align-items:center;gap:22px;color:var(--muted);font-size:11px}.hero-aside strong{display:block;color:var(--text);font-size:21px;font-weight:500;letter-spacing:-.7px;margin-bottom:6px}.hero-aside i{height:35px;width:1px;background:var(--border)}.label{font-size:11px;color:var(--muted);font-weight:500}.eyebrow-label{font:9px var(--mono);letter-spacing:1px;color:var(--muted);text-transform:uppercase}.surface{background:var(--surface);border:1px solid var(--border);border-radius:14px}.button,.ctl{border:1px solid var(--border);border-radius:8px;padding:10px 14px;background:var(--raised);font-size:11px;transition:background .15s,border-color .15s;white-space:nowrap}.button:hover,.ctl:hover{border-color:#54676e;background:#1c2a31}.button.primary,.ctl.primary{background:var(--mint);border-color:var(--mint);color:#152012;font-weight:650}.button.primary:hover,.ctl.primary:hover{background:#cdfd9d}.button.small{padding:7px 10px}.pill{border:1px solid var(--border);border-radius:20px;padding:5px 9px;font:9px var(--mono);color:var(--muted);white-space:nowrap}.muted{color:var(--muted)}.studio-footer{display:flex;justify-content:space-between;gap:20px;color:#758a92;font:10px/1.7 var(--mono);margin-top:21px;padding-top:17px;border-top:1px solid var(--border)}.studio-footer span{overflow-wrap:anywhere;min-width:0}summary{list-style:none}summary::-webkit-details-marker{display:none}details>summary:after{content:'+';float:right;font-weight:400;color:var(--muted);font-size:17px;line-height:1}details[open]>summary:after{content:'−'}pre{font:11px/1.7 var(--mono);white-space:pre-wrap;overflow-wrap:anywhere;color:var(--muted)}select{background:var(--raised);border:1px solid var(--border);border-radius:8px;padding:10px 30px 10px 11px;min-width:0;text-overflow:ellipsis}input[type=range]{accent-color:var(--mint)}.empty{color:var(--muted);font-size:12px;line-height:1.7;margin:0}
@media(max-width:1100px){.studio-shell{padding:0 24px 24px}.app-nav{gap:20px}.hero-aside{gap:14px}.studio-hero{padding-top:28px}}
@media(max-width:760px){.studio-shell{padding:0 16px 22px}.app-nav{flex-wrap:wrap;gap:14px;padding:18px 0 15px}.wordmark{font-size:18px}.wordmark small{display:none}.app-tabs{order:3;width:100%}.app-tabs a{flex:1;justify-content:center;padding:9px}.nav-status{font-size:9px}.studio-hero{padding:26px 0 23px}.studio-hero h1{font-size:33px;letter-spacing:-1.4px}.studio-hero p{font-size:12px}.hero-aside{display:none}.studio-footer{flex-direction:column;gap:6px}.eyebrow{font-size:9px}.button,.ctl{padding:10px 11px}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
'''

MARK = '<svg viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M5 24V16a5 5 0 0 1 5-5h12M18 6l5 5-5 5M27 8v8a5 5 0 0 1-5 5H10m4-5-5 5 5 5" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>'

def navigation(active):
    system = ' aria-current="page"' if active == 'system' else ''
    compare = ' aria-current="page"' if active == 'compare' else ''
    status = '<span id="connection">Gemini API</span>' if active == 'compare' else 'Interactive simulation'
    return f'''<nav class="app-nav" aria-label="Main navigation"><a class="wordmark" href="/">{MARK}AgentReroute<small>STUDIO</small></a><div class="app-tabs"><a href="/"{system}><svg class="tab-icon" viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="M3 3h4v4H3zm6 6h4v4H9zM5 7v4h4M7 5h4v4" stroke="currentColor"/></svg>Live system</a><a href="/compare"{compare}><svg class="tab-icon" viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="M3 4h10M3 8h10M3 12h10M6 2v12M10 2v12" stroke="currentColor"/></svg>Compare engines</a></div><div class="nav-status"><span class="status-dot"></span>{status}</div></nav>'''
